import fs from 'node:fs/promises';
import path from 'node:path';

// Resolved absolute path to the workspace `data` directory.
// import.meta.url resolves to a file:// URL, so pathname yields a
// platform-appropriate absolute path without requiring any cwd assumptions.
const DATA_DIR = path.resolve(new URL('./data', import.meta.url).pathname);

const FILE_METADATA_TOOL = {
  name: 'file_metadata',
  description:
    'Return metadata for a file located under the data directory: its relative path, byte size, and lowercase extension. Does not expose file contents.',
  inputSchema: {
    type: 'object',
    additionalProperties: false,
    required: ['path'],
    properties: {
      path: {
        type: 'string',
        minLength: 1,
        description:
          'Posix-style relative path to a regular file inside the data directory (e.g. "readme.txt" or "subdir/notes.md").'
      }
    }
  }
};

export async function listTools() {
  return [FILE_METADATA_TOOL];
}

function ensureInsideData(absCandidate) {
  const rel = path.relative(DATA_DIR, absCandidate);
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error(`Path escapes the data directory: ${rel || rel === ''}`);
  }
  return rel.split(path.sep).join('/');
}

export async function callTool(name, args) {
  if (name !== FILE_METADATA_TOOL.name) {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object') {
    throw new Error('Arguments must be a JSON object');
  }
  if (typeof args.path !== 'string' || args.path.length === 0) {
    throw new Error('Missing required argument: path (string)');
  }
  if (args.path.includes('\0')) {
    throw new Error('Invalid path: contains NUL byte');
  }
  if (path.isAbsolute(args.path)) {
    throw new Error('Absolute paths are not allowed; provide a path relative to the data directory');
  }

  // Normalize and reject obvious traversal attempts before touching the filesystem.
  const normalized = path.posix.normalize(args.path.replace(/\\/g, '/'));
  if (normalized === '..' || normalized.startsWith('../') || normalized.includes('/../') || normalized.endsWith('/..')) {
    throw new Error('Path traversal is not allowed');
  }

  const absolute = path.resolve(DATA_DIR, normalized);
  const relative = ensureInsideData(absolute);

  let stat;
  try {
    stat = await fs.stat(absolute);
  } catch (err) {
    if (err && err.code === 'ENOENT') {
      throw new Error(`File not found: ${args.path}`);
    }
    throw err;
  }
  if (!stat.isFile()) {
    throw new Error(`Not a regular file: ${args.path}`);
  }

  const ext = path.extname(absolute).toLowerCase();
  const text = [
    `path: ${relative}`,
    `size: ${stat.size} bytes`,
    `extension: ${ext}`
  ].join('\n');

  return {
    content: [{ type: 'text', text }]
  };
}

